var lhs := K.Drop(K.Put(K.Put(m,k,x),j,y),k);
    var inner := K.Put(m,k,x);
    var outer := K.Put(inner,j,y);
    O1.PutKeys(m,k,x);
    O1.PutKeys(inner,j,y);
    O1.DropKeys(outer,k);
    O1.DropKeys(m,k);
    if k == j {
      var rhs := K.Drop(m,k);
      assert lhs.Keys == rhs.Keys;
      forall q | q in lhs ensures q in rhs && lhs[q] == rhs[q] {
        O2.DropAt(outer,k,q);
        if q != j { O2.PutAt(m,k,x,q); }
        O2.DropAt(m,k,q);
        if q == j {
          O2.PutAt(inner,j,y,q);
        } else {
          O2.PutAt(inner,j,y,q);
        }
      }
      A.Equal(lhs,rhs);
    } else {
      var rhs := K.Put(K.Drop(m,k),j,y);
      var dropM := K.Drop(m,k);
      O1.PutKeys(dropM,j,y);
      assert lhs.Keys == rhs.Keys;
      forall q | q in lhs ensures q in rhs && lhs[q] == rhs[q] {
        O2.DropAt(outer,k,q);
        if q != j { O2.PutAt(m,k,x,q); }
        if q == j {
          O2.PutAt(inner,j,y,q);
          O2.PutAt(dropM,j,y,q);
        } else {
          O2.PutAt(inner,j,y,q);
          O2.PutAt(dropM,j,y,q);
          O2.DropAt(m,k,q);
        }
      }
      A.Equal(lhs,rhs);
    }
